{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C20"],
      "claim": "In mice, HI-236 reached brain concentrations comparable to plasma after systemic administration, indicating direct BBB penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "In a first-in-human PET study, [18F]2 showed good brain penetration with peak whole-brain uptake of 5.0–6.0% i.D., providing direct human evidence of meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "AF-DX384 is reported to have low BBB penetration, which limited its use in PET imaging, providing a contrasting example of insufficient CNS access.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Most structurally related compounds with direct systemic CNS evidence show meaningful brain uptake across rodents and humans, while one related compound fails. Overall, the balance of transferable evidence supports meaningful CNS access.",
  "evidence_gaps": [
    "Morgan similarities are low (0.18–0.22), limiting structural transferability.",
    "One related PET tracer showed low brain uptake in pigs despite good uptake in other species, indicating possible species-dependent variability.",
    "No direct query-specific experimental record is available."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

